files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #f0f4f8;
  color: #1e293b;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.card {
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  padding: 2rem;
  width: 100%;
  max-width: 800px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  color: #0f172a;
  margin-bottom: 0.25rem;
}

.subtitle {
  color: #64748b;
  margin-bottom: 1.5rem;
  font-size: 0.95rem;
}

.line-item {
  display: grid;
  grid-template-columns: 2fr 0.8fr 1fr 1fr auto;
  gap: 0.5rem;
  align-items: center;
  margin-bottom: 0.5rem;
}

.header-row {
  font-weight: 600;
  color: #475569;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding-bottom: 0.25rem;
  border-bottom: 2px solid #e2e8f0;
  margin-bottom: 0.75rem;
}

.line-item input {
  width: 100%;
  padding: 0.5rem 0.6rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.line-item input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.line-total {
  font-weight: 600;
  color: #0f172a;
  padding: 0.5rem 0;
  text-align: right;
}

.remove-btn {
  background: none;
  border: none;
  color: #ef4444;
  cursor: pointer;
  font-size: 1.2rem;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  transition: background 0.15s;
}

.remove-btn:hover {
  background: #fee2e2;
}

.remove-btn:focus-visible {
  outline: 2px solid #ef4444;
  outline-offset: 2px;
}

.btn {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: background 0.15s, transform 0.1s;
}

.btn.secondary {
  background: #e2e8f0;
  color: #1e293b;
  margin-bottom: 1.5rem;
}

.btn.secondary:hover {
  background: #cbd5e1;
}

.btn.secondary:active {
  transform: scale(0.98);
}

.btn.secondary:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.totals {
  border-top: 2px solid #e2e8f0;
  padding-top: 1rem;
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.4rem 0;
  font-size: 1rem;
}

.total-row label {
  color: #475569;
}

.total-row input {
  width: 100px;
  padding: 0.4rem 0.6rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 1rem;
  font-family: inherit;
  text-align: right;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.total-row input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.grand-total {
  font-weight: 700;
  font-size: 1.25rem;
  color: #0f172a;
  border-top: 2px solid #e2e8f0;
  margin-top: 0.5rem;
  padding-top: 0.75rem;
}

@media (max-width: 600px) {
  .line-item {
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    padding: 0.75rem;
    background: #f8fafc;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    margin-bottom: 0.75rem;
  }

  .header-row {
    display: none;
  }

  .line-item input {
    font-size: 0.95rem;
  }

  .line-total {
    text-align: left;
  }

  .remove-btn {
    justify-self: end;
  }

  .card {
    padding: 1.25rem;
  }
}

[hidden] {
  display: none !important;
}

const lineItemsContainer = document.getElementById('line-items');
const addItemBtn = document.getElementById('add-item');
const taxRateInput = document.getElementById('tax-rate');
const subtotalEl = document.getElementById('subtotal');
const taxEl = document.getElementById('tax');
const grandTotalEl = document.getElementById('grand-total');

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function calculateTotals() {
  let subtotal = 0;
  const lineItems = lineItemsContainer.querySelectorAll('.line-item:not(.header-row)');
  lineItems.forEach(item => {
    const qty = parseFloat(item.querySelector('.qty').value) || 0;
    const price = parseFloat(item.querySelector('.price').value) || 0;
    const lineTotal = qty * price;
    item.querySelector('.line-total').textContent = formatCurrency(lineTotal);
    subtotal += lineTotal;
  });

  const taxRate = parseFloat(taxRateInput.value) || 0;
  const tax = subtotal * (taxRate / 100);
  const grandTotal = subtotal + tax;

  subtotalEl.textContent = formatCurrency(subtotal);
  taxEl.textContent = formatCurrency(tax);
  grandTotalEl.textContent = formatCurrency(grandTotal);
}

function createLineItem() {
  const div = document.createElement('div');
  div.className = 'line-item';

  const descLabel = document.createElement('label');
  descLabel.className = 'visually-hidden';
  descLabel.textContent = 'Description';
  descLabel.htmlFor = 'desc-' + Date.now();
  const descInput = document.createElement('input');
  descInput.type = 'text';
  descInput.className = 'desc';
  descInput.id = descLabel.htmlFor;
  descInput.placeholder = 'Item description';
  descInput.setAttribute('aria-label', 'Description');

  const qtyLabel = document.createElement('label');
  qtyLabel.className = 'visually-hidden';
  qtyLabel.textContent = 'Quantity';
  qtyLabel.htmlFor = 'qty-' + Date.now();
  const qtyInput = document.createElement('input');
  qtyInput.type = 'number';
  qtyInput.className = 'qty';
  qtyInput.id = qtyLabel.htmlFor;
  qtyInput.min = '0';
  qtyInput.step = '1';
  qtyInput.value = '1';
  qtyInput.setAttribute('aria-label', 'Quantity');

  const priceLabel = document.createElement('label');
  priceLabel.className = 'visually-hidden';
  priceLabel.textContent = 'Unit Price';
  priceLabel.htmlFor = 'price-' + Date.now();
  const priceInput = document.createElement('input');
  priceInput.type = 'number';
  priceInput.className = 'price';
  priceInput.id = priceLabel.htmlFor;
  priceInput.min = '0';
  priceInput.step = '0.01';
  priceInput.value = '0.00';
  priceInput.setAttribute('aria-label', 'Unit Price');

  const lineTotalSpan = document.createElement('span');
  lineTotalSpan.className = 'line-total';
  lineTotalSpan.textContent = '$0.00';

  const removeBtn = document.createElement('button');
  removeBtn.className = 'remove-btn';
  removeBtn.textContent = '×';
  removeBtn.setAttribute('aria-label', 'Remove line item');
  removeBtn.addEventListener('click', () => {
    div.remove();
    calculateTotals();
  });

  div.appendChild(descLabel);
  div.appendChild(descInput);
  div.appendChild(qtyLabel);
  div.appendChild(qtyInput);
  div.appendChild(priceLabel);
  div.appendChild(priceInput);
  div.appendChild(lineTotalSpan);
  div.appendChild(removeBtn);

  descInput.addEventListener('input', calculateTotals);
  qtyInput.addEventListener('input', calculateTotals);
  priceInput.addEventListener('input', calculateTotals);

  return div;
}

function addLineItem() {
  lineItemsContainer.appendChild(createLineItem());
  calculateTotals();
}

addItemBtn.addEventListener('click', addLineItem);
taxRateInput.addEventListener('input', calculateTotals);

// Add one initial line item
addLineItem();

// Add visually-hidden class for labels if not present
const style = document.createElement('style');
style.textContent = `
  .visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
`;
document.head.appendChild(style);
